input_script:
var boardRequest = input.query || input || {};
var boardProjects = Array.isArray(boardRequest.projects) ? boardRequest.projects : (boardRequest.projects ? [boardRequest.projects] : []);
var boardScopes = [];
for (var bs = 0; bs < boardProjects.length; bs++) {
  var bp = boardProjects[bs];
  if (!bp) continue;
  var bk = typeof bp === 'object' ? String(bp.jiraproject || '').trim() : '';
  var bn = typeof bp === 'string' ? bp.trim() : String(bp.projectname || '').trim();
  if (!bk && !bn) continue;
  boardScopes.push({project_key: bk, project_name: bn,
    board_id: typeof bp === 'object' ? String(bp.boardid || '').trim() : '',
    connection_id: String((typeof bp === 'object' && bp.connectionid) || boardRequest.connectionid || '').trim()});
}

var scopeRequest = input.query || input || {};
var scopeProjects = Array.isArray(scopeRequest.projects) ? scopeRequest.projects : (scopeRequest.projects ? [scopeRequest.projects] : []);
var projectKeys = [];
for (var si = 0; si < scopeProjects.length; si++) {
  var sp = scopeProjects[si];
  var sk = typeof sp === 'object' && sp !== null ? String(sp.jiraproject || '').trim() : '';
  if (sk && projectKeys.indexOf(sk) < 0) projectKeys.push(sk);
}
var hasIssueScope = 0;
for (var scopeIndex = 0; scopeIndex < scopeProjects.length; scopeIndex++) {
  var scopeProject = scopeProjects[scopeIndex];
  if (typeof scopeProject === 'string' && scopeProject.trim()) hasIssueScope = 1;
  if (scopeProject && typeof scopeProject === 'object' &&
      (String(scopeProject.projectname || '').trim() || String(scopeProject.jiraproject || '').trim())) hasIssueScope = 1;
}
if (projectKeys.length === 0) projectKeys = ['__NONE__'];

var q = input.query || input;
var projects = Array.isArray(q.projects) ? q.projects : (q.projects ? [q.projects] : []);
var excludeProjects = Array.isArray(q.excludeProjects) ? q.excludeProjects : [];
var from = Number(q.from) || 0;
var to = Number(q.to) || 0;
var jiraproject = q.jiraproject || '';
var userwhitelist = Array.isArray(q.userwhitelist) ? q.userwhitelist : (q.userwhitelist ? [q.userwhitelist] : []);

var validProjects = [];
var idx;
for (idx = 0; idx < projects.length; idx++) {
  var p = projects[idx];
  if (typeof p === 'string' && p.trim() !== '') validProjects.push(p);
  else if (typeof p === 'object' && p !== null && (p.projectname || '').trim() !== '') validProjects.push(p);
}

var projectnames = [];
var projectFilters = [];
for (idx = 0; idx < validProjects.length; idx++) {
  var proj = validProjects[idx];
  var name = typeof proj === 'string' ? proj : (proj.projectname || '');
  if (!name) continue;
  projectnames.push(name);
  var components = (typeof proj === 'object' && Array.isArray(proj.components)) ? proj.components : [];
  var labels = (typeof proj === 'object' && Array.isArray(proj.labels)) ? proj.labels : [];
  if (components.length > 0 || labels.length > 0) {
    projectFilters.push({ projectname: name, components: components, labels: labels });
  }
}

var filterByProject = projectnames.length > 0 ? 1 : 0;
if (projectnames.length === 0) projectnames = ['__dummy__'];

var filterExclude = excludeProjects.length > 0 ? 1 : 0;
var safeExcludeProjects = excludeProjects.length > 0 ? excludeProjects : ['__dummy__'];

var hasUserwhitelist = userwhitelist.length > 0 ? 1 : 0;
var safeUserwhitelist = userwhitelist.length > 0 ? userwhitelist : ['__dummy__'];

var lookbackTo = to > 0 ? to - (90 * 24 * 60 * 60) : 0;

({
  boardScopes: JSON.stringify(boardScopes),
  projectKeys: projectKeys,
  hasIssueScope: hasIssueScope,
  projectnames: projectnames,
  excludeProjects: safeExcludeProjects,
  filterByProject: filterByProject,
  filterExclude: filterExclude,
  projectFilters: JSON.stringify(projectFilters),
  from: from,
  to: to,
  lookbackTo: lookbackTo,
  jiraproject: jiraproject,
  userwhitelist: safeUserwhitelist,
  hasUserwhitelist: hasUserwhitelist
})

output_script:
var data = results.main || [];

function getMinutes(issue) {
  if (issue.lead_time_minutes != null && issue.lead_time_minutes > 0) {
    return issue.lead_time_minutes;
  }
  var created = new Date(issue.created_date);
  var end = new Date(issue.resolution_date);
  if (isNaN(created.getTime()) || isNaN(end.getTime())) return null;
  return (end - created) / (1000 * 60);
}

var baselineMinutes = [];
var displayIssues = [];
var i;

for (i = 0; i < data.length; i++) {
  var row = data[i];
  if (row.status === 'TODO' || row.status === 'IN_PROGRESS') continue;
  if (!row.resolution_date) continue;
  if (!row.created_date && !row.lead_time_minutes) continue;
  var mins = getMinutes(row);
  if (mins == null || mins < 0) continue;
  baselineMinutes.push(mins);
  if (row.in_display_range === 1) {
    displayIssues.push({
      issue_key: row.issue_key,
      minutes: mins,
      url: row.url || null,
      project: row.project_name || '—',
      title: row.title || ''
    });
  }
}

var result;

if (baselineMinutes.length === 0) {
  result = { error: "No issues available for z-score baseline (mu_log, sigma_log)" };
} else {
  var logTimes = [];
  for (i = 0; i < baselineMinutes.length; i++) {
    logTimes.push(Math.log(baselineMinutes[i] + 1));
  }
  var sum = 0;
  for (i = 0; i < logTimes.length; i++) sum += logTimes[i];
  var mu_log = sum / logTimes.length;
  var variance = 0;
  for (i = 0; i < logTimes.length; i++) {
    variance += Math.pow(logTimes[i] - mu_log, 2);
  }
  variance = variance / logTimes.length;
  var sigma_log = Math.sqrt(variance) || 1e-10;

  if (displayIssues.length === 0) {
    result = { error: "No issues with valid resolution time for z-score calculation" };
  } else {
    var scored = [];
    for (i = 0; i < displayIssues.length; i++) {
      var di = displayIssues[i];
      var log_t = Math.log(di.minutes + 1);
      var z_score = (log_t - mu_log) / sigma_log;
      var category;
      if (z_score < -1.0) category = "Fast";
      else if (z_score > 1.0) category = "Slow";
      else category = "Average";
      scored.push({
        key: di.issue_key,
        z: z_score,
        category: category,
        minutes: di.minutes,
        link: di.url,
        project: di.project,
        title: di.title
      });
    }

    var categoryOrder = ["Fast", "Average", "Slow"];
    var counts = { Fast: 0, Average: 0, Slow: 0 };
    for (i = 0; i < scored.length; i++) counts[scored[i].category] += 1;

    var barData = [];
    for (i = 0; i < categoryOrder.length; i++) barData.push(counts[categoryOrder[i]]);

    var categoryMedianDays = {};
    var ci;
    for (ci = 0; ci < categoryOrder.length; ci++) {
      var cat2 = categoryOrder[ci];
      var mins2 = scored.filter(function(r) { return r.category === cat2; })
        .map(function(r) { return r.minutes; })
        .sort(function(a, b) { return a - b; });
      if (mins2.length === 0) { categoryMedianDays[cat2] = 0; continue; }
      var mid = Math.floor(mins2.length / 2);
      var median = mins2.length % 2 === 0 ? (mins2[mid - 1] + mins2[mid]) / 2 : mins2[mid];
      categoryMedianDays[cat2] = Math.round((median / (60 * 24)) * 10) / 10;
    }

    var barLabels = [];
    for (ci = 0; ci < categoryOrder.length; ci++) {
      var cat3 = categoryOrder[ci];
      barLabels.push(counts[cat3] > 0 ? cat3 + ' (median: ' + categoryMedianDays[cat3] + 'd)' : cat3);
    }

    var barColors = [
      'rgba(34, 197, 94, 0.8)',
      'rgba(107, 114, 128, 0.8)',
      'rgba(239, 68, 68, 0.8)'
    ];

    var extraLabels = [
      { label: "Issue Key", field: "id" },
      { label: "URL", field: "url" },
      { label: "Z-Score", field: "z_score" },
      { label: "Resolution Time (days)", field: "days" }
    ];
    var fastIssues = [];
    var averageIssues = [];
    var slowIssues = [];
    for (ci = 0; ci < scored.length; ci++) {
      var si = scored[ci];
      var sDays = (si.minutes / (60 * 24)).toFixed(2);
      var row = { id: si.key, url: si.link || '', z_score: Number(si.z.toFixed(2)), days: Number(sDays) };
      if (si.category === 'Fast') fastIssues.push(row);
      else if (si.category === 'Slow') slowIssues.push(row);
      else averageIssues.push(row);
    }

    result = {
      type: "bar",
      label: "Issue Z-Score (resolution time)",
      description: "Z-score of issue resolution time (created to resolved) over a baseline. Green = Fast (z < -1), Gray = Average (-1 <= z <= 1), Red = Slow (z > 1). Baseline uses a 90-day lookback from the end of the selected time range.",
      data: {
        labels: barLabels,
        datasets: [{
          label: 'Issue count',
          data: barData,
          backgroundColor: barColors,
          borderColor: [
            'rgba(34, 197, 94, 1)',
            'rgba(107, 114, 128, 1)',
            'rgba(239, 68, 68, 1)'
          ],
          borderWidth: 1
        }],
        extra: {
          config: [
            { location: "appendToAnalytics", type: "openList", field: "fast_issues", template: "Show Fast Issues", labels: extraLabels },
            { location: "appendToAnalytics", type: "openList", field: "average_issues", template: "Show Average Issues", labels: extraLabels },
            { location: "appendToAnalytics", type: "openList", field: "slow_issues", template: "Show Slow Issues", labels: extraLabels }
          ],
          data: {
            fast_issues: fastIssues,
            average_issues: averageIssues,
            slow_issues: slowIssues
          }
        }
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        indexAxis: 'y',
        scales: {
          x: {
            title: { display: true, text: 'Issue count' },
            grid: { display: true },
            beginAtZero: true,
            ticks: { stepSize: 1 }
          },
          y: {
            title: { display: true, text: 'Category' },
            grid: { display: false }
          }
        },
        plugins: {
          legend: { display: true, position: 'top' },
          tooltip: {}
        }
      }
    };
  }
}

